CREATE TABLE `faculty_research_supervisions` (
  `research_supervision_id` int NOT NULL,
  `faculty_id` int NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`research_supervision_id`,`faculty_id`),
  KEY `idx_faculty_research_supervisions_faculty` (`faculty_id`),
  CONSTRAINT `fk_frs_faculty` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_frs_supervision` FOREIGN KEY (`research_supervision_id`) REFERENCES `research_supervisions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
