INSERT INTO `hod_messages` VALUES (2,4,'Dr. Siddhartha Chauhan','It is with great pleasure that I write this in the capacity of the Head of the Department (HOD) of the Computer Science and Engineering (CSE) Department at NIT Hamirpur. I thank all the faculty members, students, and staff of our esteemed department for their continuous efforts every day in maintaining the excellence and reputation of our department','https://portfolios.nith.ac.in/uploads/member_details/62.jpg','2025-04-18 14:53:13','2025-04-18 14:53:13');
