--
-- Table structure for table `placement_stats`
--

DROP TABLE IF EXISTS `placement_stats`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `placement_stats` (
  `id` int NOT NULL AUTO_INCREMENT,
  `branch` varchar(50) NOT NULL,
  `year` year NOT NULL,
  `candidates` smallint unsigned NOT NULL,
  `placed` smallint unsigned NOT NULL,
  `jobs_offered` smallint unsigned NOT NULL,
  `max_ctc` decimal(10,2) DEFAULT NULL,
  `placed_percent` decimal(5,2) GENERATED ALWAYS AS (round(((`placed` * 100.0) / nullif(`candidates`,0)),2)) STORED,
  `offers_percent` decimal(5,2) GENERATED ALWAYS AS (round(((`jobs_offered` * 100.0) / nullif(`candidates`,0)),2)) STORED,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_placement_stats_branch_year` (`branch`,`year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

