INSERT INTO `posts` VALUES (4,'achievement','5th International Conference on Machine Learning, Image Processing, Network Security, and Data Sciences (MIND 2023)','Department of CSE, NIT Hamirpur has successfully orgainized 5th International Conference on Machine Learning, Image Processing, Network Security, and Data Sciences (MIND 2023) on 21st and 22nd of December 2023','https://res.cloudinary.com/dha8atrgz/image/upload/v1725899222/Screenshot_from_2024-09-09_21-56-30_cy3pch.png','https://mind2023.nith.ac.in/','2024-09-06','2024-09-17 02:08:27','2025-02-02 17:57:03'),(5,'achievement','Recent Advancements in Artificial Intelligence and Internet of Things (RAAI-2024)','Department of CSE, NIT Hamirpur has successfully orgainized 5 Days e-Workshop on Recent Advancements in Artificial Intelligence and Internet of Things (RAAI-2024) from 08-12 April 2024','https://res.cloudinary.com/dha8atrgz/image/upload/v1725899321/Screenshot_from_2024-09-09_21-58-05_qsx0pt.png','https://nith.ac.in/uploads/topics/csed-workshop-ai17121269353999.pdf','2024-09-06','2024-09-17 02:08:27','2025-02-02 17:57:06'),(6,'achievement','Research Applications of Deep Learning','Department of CSE, NIT Hamirpur has successfully orgainized 5 Days e-STC on Research Applications of Deep Learning from 01-05 July 2024','https://res.cloudinary.com/dvnrlqqpq/image/upload/v1749014936/rgsiauf7yh1sy8aer5yo.jpg','https://nith.ac.in/uploads/topics/estc-csed17177438577130.pdf','2025-06-04','2024-09-17 02:08:27','2025-06-04 05:34:17'),(11,'achievement','2nd International Conference on Artificial Intelligence, Machine Learning & Intelligent Systems (ICAMS-2025)','The 2nd International Conference on Artificial Intelligence, Machine Learning & Intelligent Systems (ICAMS 2025) was scheduled on February 7–8, 2025, at the National Institute of Technology (NIT) Hamirpur, Himachal Pradesh, India. Organized by the Department of Computer Science and Engineering at NIT Hamirpur. The Organising Chairman is Dr. Naveen Chauhan, DoCSE, NIT Hamirpur. The Organising Secretary is Dr. Mohammad Khalid Pradit and Dr. Ajay Kumar Mallick, DoCSE, NIT Hamirpur. The inaugural ceremony of ICAMS 2025 was held on February 7, 2025, at the National Institute of Technology (NIT) Hamirpur in presence of Prof. Hiralal Murlidhar Suryawanshi, Director of NIT Hamirpur, Prof. Archana Santosh Nanoty, Registrar, NIT Hamirpur, and other expert from reputed institutes. The Valedictory Ceremony of the ICAMS 2025 was held on 8th February 2025 at NIT Hamirpur, marking the successful conclusion of the two-day conference in the esteemed presence of Prof. H.M. Suryawanshi, Director, NIT Hamirpur, Prof. Archana Santosh Nanoty, Registrar and other delegates.','https://res.cloudinary.com/dvnrlqqpq/image/upload/v1749015564/clbtxoenukldqigdws1e.jpg','https://sites.google.com/nith.ac.in/icams2025/home','2025-06-13','2025-06-04 05:44:44','2025-06-04 05:52:00'),(12,'achievement','e-STC ON Mobile Device Security during 27-31 January 2025','The primary objective of this short-term course is to equip participants with in-depth understanding of the latest trends and advancements in the field of Mobile Device Security. This short-term course aims to provide insights into advancements in mobile and wireless security. Key topics include reconnaissance, 5G security, malware analysis, cryptography, and machine learning applications. Participants will also explore opportunistic networks, device-to-device communication, and attack graphs. Led by experts, the course equips professionals and researchers with skills to address modern cybersecurity challenges.','https://res.cloudinary.com/dvnrlqqpq/image/upload/v1749528583/bppbvfzidwo1jbxsp6gj.jpg','https://drive.google.com/file/d/1uMg5gFGlNDoysiLSo8sBxpr_OmhxSDGH/view?usp=drivesdk','2025-06-10','2025-06-10 04:14:59','2025-06-10 04:14:59'),(13,'achievement','Faculty Updation Programme on Mobile Device Security during 24-28 Feb-2025','The aims this event is to enhance faculty and researchers\' knowledge and skills in mobile device security, addressing both current challenges and technological advancements. It focuses on practical training in security technologies, experiments, and simulations, while fostering collaboration to tackle industrial and research challenges in network and information security.','https://res.cloudinary.com/dvnrlqqpq/image/upload/v1749528746/dkoa0yhls1gorpvcxqpc.jpg','https://drive.google.com/file/d/1-PrAKjUj6LZb-1nqzHPjLphX2EIKi9Er/view?usp=drivesdk','2025-06-10','2025-06-10 04:17:42','2025-06-10 04:17:42'),(14,'achievement','Bootcamp On Mobile Device Security during 6-7 March 2025','This intensive bootcamp offers a comprehensive introduction to key areas in mobile and AI security. Participants will gain foundational knowledge in mobile security, explore recent mobile attack techniques, and learn practical skills like reverse engineering Android apps and performing mobile forensics. The bootcamp also delves into critical aspects of AI safety, including the causes and risks of LLM hallucinations, and methods to ensure trust and reliability in large language models. Designed for cybersecurity enthusiasts, developers, and researchers, the program blends hands-on learning with real-world case studies to build expertise in securing modern mobile and AI systems.','https://res.cloudinary.com/dvnrlqqpq/image/upload/v1749528863/txuzds3wgeq0txltnl4j.jpg','https://drive.google.com/file/d/19m4x2VMWvvB4S3ceb3-uHPVgKXOjhrb2/view?usp=drivesdk','2025-06-10','2025-06-10 04:19:40','2025-06-10 04:19:40');
/*!40000 ALTER TABLE `posts` ENABLE KEYS */;
UNLOCK TABLES;

